<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { call, createResource, toast } from 'frappe-ui'
import { statusPillClass } from '../data/ttsStatus'
import { currentUser } from '../data/user'
import { refreshCsrfToken } from '../data/session'
import { openAttachment } from '../composables/pdfViewer'
import { useBackNavigation } from '../composables/useBackNavigation'
import { kompresFoto } from '../composables/imageCompress'
import { siapkanBerkas, unggahLampiran } from '../composables/fileUpload'

const DOCTYPE = 'TTS'
const route = useRoute()
const { backTarget, backLabel } = useBackNavigation({ name: 'Tts' }, 'TTS')
const name = computed(() => route.params.name)

const displayTitle = computed(() => doc.data?.name || name.value)

// ---- Aksi dokumen ----------------------------------------------------------
// Tombol "Action" menampung tiga aksi yang sama dengan form TTS di desk:
//   Close TTS -> tts.js
//   Oper PIC  -> public/js/oper_pic_actions.js
//   Regis     -> public/js/monitoring_document_actions.js
// Syaratnya sengaja TIDAK dihitung ulang di sini: portal memakai state yang
// dikirim server (get_oper_pic_state / get_status_monitoring_doc) supaya
// aturannya tidak bercabang antara desk dan portal. Yang dicerminkan di klien
// hanya tipe close per role — persis tipe_options() di close_document_dialog.js.
const ADMIN_CLOSE_ROLES = ['System Manager', 'Admin Coll', 'Head Admin Coll']
const FIELD_ROLES = ['Field Coll', 'Head Field Coll']
const ALL_CLOSE_TYPES = ['Dipakai', 'Rusak', 'Hilang']

// Role belum termuat (atau fetch-nya gagal) bukan alasan menyembunyikan aksi:
// server tetap menolak yang tidak berhak, sedangkan menyembunyikan tombol dari
// orang yang berhak tidak bisa dipulihkan sendiri oleh pemakainya.
const rolesUnknown = computed(() => !currentUser.rolesLoaded || !currentUser.roles.length)
function hasAnyRole(list) {
	return list.some((r) => currentUser.roles.includes(r))
}
const closeTypeOptions = computed(() => {
	if (rolesUnknown.value || hasAnyRole(ADMIN_CLOSE_ROLES)) return ALL_CLOSE_TYPES
	if (hasAnyRole(FIELD_ROLES)) return ['Dipakai']
	return []
})

// TTS bisa di-close HANYA saat status "Belum Terpakai" (sudah diregistrasi ke
// kolektor). Selaras backend close_tts() yang menolak selain status ini pada
// jalur "Melalui Registrasi" — satu-satunya jalur yang dipakai portal.
const canClose = computed(
	() => doc.data?.status === 'Belum Terpakai' && closeTypeOptions.value.length > 0
)

// State aksi dari server; keputusan finalnya tetap di endpoint masing-masing.
const operState = reactive({
	can_submit: false,
	direct_by_admin: false,
	current_pic: '',
	current_nama_pic: '',
	// Pengajuan yang masih menunggu + apakah user ini boleh memutuskannya.
	// Server sudah menolak pengaju menyetujui pengajuannya sendiri, jadi
	// can_review sekaligus menyembunyikan tombol yang pasti gagal.
	can_review: false,
	pending: null,
})
const monState = reactive({ can_report: false })

async function loadActionState() {
	const [oper, mon] = await Promise.all([
		// Keduanya melempar PermissionError untuk yang tidak berhak — itu jawaban
		// yang sah ("tidak ada aksi"), bukan kegagalan halaman.
		call('juragan.collection.oper_pic.get_oper_pic_state', {
			doctype: DOCTYPE,
			name: name.value,
		}).catch(() => null),
		call('juragan.collection.monitoring_dokumen.get_status_monitoring_doc', {
			doctype: DOCTYPE,
			name: name.value,
		}).catch(() => null),
	])
	operState.can_submit = !!oper?.can_submit
	operState.direct_by_admin = !!oper?.direct_by_admin
	operState.current_pic = oper?.current_pic || ''
	operState.current_nama_pic = oper?.current_nama_pic || ''
	operState.can_review = !!oper?.can_review
	operState.pending = oper?.pending || null
	monState.can_report = !!mon?.can_report
}

const actions = computed(() => {
	const list = []
	if (canClose.value) list.push({ key: 'close', label: 'Close TTS' })
	if (operState.can_submit)
		list.push({
			key: 'oper',
			label: operState.direct_by_admin ? 'Oper PIC' : 'Ajukan Oper PIC',
		})
	// Saat ada pengajuan menggantung, can_submit pasti false — jadi kedua entri
	// ini tidak pernah muncul bersamaan. Labelnya sengaja sama: satu pintu
	// "Oper PIC", isinya menyesuaikan keadaan dokumen.
	if (operState.can_review) list.push({ key: 'oper_review', label: 'Oper PIC' })
	if (monState.can_report) list.push({ key: 'regis', label: 'Regis' })
	return list
})
const hasActions = computed(() => actions.value.length > 0)

const actionOpen = ref(false)
function openActions() {
	actionOpen.value = true
}
function runAction(key) {
	actionOpen.value = false
	if (key === 'close') openClose()
	else if (key === 'oper') openOper()
	else if (key === 'oper_review') openReview()
	else if (key === 'regis') openRegis()
}

// Toast frappe-ui tak auto-dismiss di webview (timer ikut fokus window) → hapus
// manual setelah beberapa detik.
function autoToast(type, message) {
	const id = toast[type](message)
	setTimeout(() => toast.remove(id), 3500)
}

// ---- Close TTS (tipe) ------------------------------------------------------
const CLOSE_TYPES = [
	{
		key: 'Dipakai',
		label: 'Dipakai',
		iconWrap: 'bg-ui-surface-green-100 text-ui-ink-green-600',
	},
	{ key: 'Rusak', label: 'Rusak', iconWrap: 'bg-ui-surface-red-100 text-ui-ink-red-600' },
	{ key: 'Hilang', label: 'Hilang', iconWrap: 'bg-ui-surface-gray-200 text-ui-ink-gray-600' },
]
// Kolektor lapangan hanya boleh tipe Dipakai — menampilkan Rusak/Hilang untuk
// mereka hanya berujung penolakan server.
const visibleCloseTypes = computed(() =>
	CLOSE_TYPES.filter((t) => closeTypeOptions.value.includes(t.key))
)
const closeOpen = ref(false)
const selectedType = ref('')
const submitting = ref(false)
const closeError = ref('')

// Form Close: field yang dipakai backend close_tts.
const form = reactive({
	sumber: '',
	no_perjanjian: '',
	nominal_bayar: null,
	tanggal_pembayaran: '',
	keterangan: '',
})

// Sumber menentukan master nasabah yang dipakai — cerminan
// NASABAH_DOCTYPE_BY_SUMBER di juragan/collection/utils.py. Server tetap yang
// menegakkan; ini hanya untuk tahu doctype apa yang dicari picker.
const NASABAH_DOCTYPE_BY_SUMBER = {
	KSP: 'Master Data Nasabah',
	JG: 'Master Data Nasabah JG',
}
const SUMBER_OPTIONS = Object.keys(NASABAH_DOCTYPE_BY_SUMBER)

// Portal hanya memakai jalur close normal (dari status "Belum Terpakai");
// close langsung dari "Stok" tetap lewat desk.
const JALUR_CLOSE = 'Melalui Registrasi'

// ---- Konteks No Perjanjian dari Aktivitas Field Collection -----------------
// Bila TTS ini sudah dipakai pada input aktivitas Field Coll (Target dan
// Realisasi), Sumber & No Perjanjian-nya diisi otomatis & dikunci.
// No Perjanjian yang sudah dipakai TTS lain TIDAK disaring: satu kontrak boleh
// memakai banyak TTS (tiap angsuran bisa TTS baru). Yang dijaga server adalah
// satu TTS hanya untuk satu kontrak.
const closeCtx = reactive({ auto: '', auto_sumber: '' })
const ctxLoading = ref(false)
const lockedNoPerjanjian = computed(() => !!closeCtx.auto)
// Sumber ikut terkunci: server menolak kombinasi Sumber/No Perjanjian yang
// berbeda dari aktivitasnya (_assert_activity_contract di tts.py), jadi
// membiarkannya bisa diganti hanya menghasilkan error saat submit.
const lockedSumber = lockedNoPerjanjian

async function loadCloseContext() {
	closeCtx.auto = ''
	closeCtx.auto_sumber = ''
	ctxLoading.value = true
	try {
		const r = await call(
			'juragan.api.local.utils_collection.get_close_no_perjanjian_context',
			{
				document_doctype: DOCTYPE,
				document: name.value,
			}
		)
		closeCtx.auto = r?.auto || ''
		closeCtx.auto_sumber = r?.auto_sumber || ''
		if (closeCtx.auto) {
			// Sumber lebih dulu — preview nasabah tidak bisa diambil tanpa itu.
			form.sumber = closeCtx.auto_sumber
			await selectNasabah({ name: closeCtx.auto })
		}
	} catch (e) {
		/* konteks gagal → user tetap bisa pilih No Perjanjian manual */
	} finally {
		ctxLoading.value = false
	}
}

// ---- Cari No Perjanjian (Master Data Nasabah) + preview info nasabah --------
const searchQuery = ref('')
const searchOpen = ref(false)
const searching = ref(false)
const searchResults = ref([])
let searchTimer = null

const preview = reactive({
	nama_nasabah: '',
	nopol: '',
	no_mesin: '',
	angsuran: null,
	angsuran_ke: '',
	tanggal_jto: '',
})
const previewLoading = ref(false)
const previewRows = computed(() => [
	{ label: 'Nama Nasabah', value: preview.nama_nasabah || '—' },
	{ label: 'Nopol', value: preview.nopol || '—' },
	{ label: 'No Mesin', value: preview.no_mesin || '—' },
	{
		label: 'Angsuran',
		value: preview.angsuran != null ? formatCurrency(preview.angsuran) : '—',
	},
	{ label: 'Angsuran ke', value: preview.angsuran_ke || '—' },
	{ label: 'Tanggal JTO', value: preview.tanggal_jto ? formatDate(preview.tanggal_jto) : '—' },
])

/** Ganti Sumber = ganti master nasabah, jadi pilihan lama tidak berlaku lagi. */
function selectSumber(s) {
	if (lockedSumber.value || form.sumber === s) return
	form.sumber = s
	form.no_perjanjian = ''
	searchQuery.value = ''
	searchResults.value = []
	searchOpen.value = false
	closeError.value = ''
	resetPreview()
}

// ---- Dropdown di dalam bottom sheet ----------------------------------------
// Daftar hasil MELAYANG di luar sheet (position: fixed) dan posisinya dihitung
// dari kotak kolomnya, jadi tinggi sheet tidak ikut berubah saat daftar dibuka.
// Arahnya ke ATAS begitu ruang di bawah tidak cukup — di sheet yang menempel
// tepi bawah layar itu keadaan yang biasa, dan daftar yang jatuh ke bawah akan
// keluar layar. Tinggi maksimalnya juga dipotong sesuai ruang yang tersedia
// supaya tidak pernah ada bagian yang tidak bisa dijangkau.
const TINGGI_DROPDOWN = 208 // setara max-h-52
const JARAK_DROPDOWN = 4
const npBox = ref(null)
const picBox = ref(null)
const npStyle = ref({})
const picStyle = ref({})

function posisiDropdown(el) {
	if (!el) return {}
	const r = el.getBoundingClientRect()
	const ruangBawah = window.innerHeight - r.bottom
	const dasar = { left: `${r.left}px`, width: `${r.width}px` }
	if (ruangBawah < TINGGI_DROPDOWN + JARAK_DROPDOWN && r.top > ruangBawah) {
		return {
			...dasar,
			bottom: `${window.innerHeight - r.top + JARAK_DROPDOWN}px`,
			maxHeight: `${Math.max(96, Math.min(TINGGI_DROPDOWN, r.top - 12))}px`,
		}
	}
	return {
		...dasar,
		top: `${r.bottom + JARAK_DROPDOWN}px`,
		maxHeight: `${Math.max(96, Math.min(TINGGI_DROPDOWN, ruangBawah - 12))}px`,
	}
}

function ukurNp() {
	npStyle.value = posisiDropdown(npBox.value)
}
function ukurPic() {
	picStyle.value = posisiDropdown(picBox.value)
}

// Papan ketik yang muncul/menutup mengubah tinggi viewport — posisinya dihitung
// ulang supaya daftar tidak tertinggal di tempat lamanya.
function ukurDropdownTerbuka() {
	if (searchOpen.value) ukurNp()
	if (picOpen.value) ukurPic()
}
onMounted(() => window.addEventListener('resize', ukurDropdownTerbuka))
onBeforeUnmount(() => window.removeEventListener('resize', ukurDropdownTerbuka))

function onSearchFocus() {
	if (lockedNoPerjanjian.value || !form.sumber) return
	searchOpen.value = true
	ukurNp()
	if (!searchResults.value.length) fetchNasabah('')
}
function onSearch() {
	if (lockedNoPerjanjian.value || !form.sumber) return
	searchOpen.value = true
	ukurNp()
	clearTimeout(searchTimer)
	searchTimer = setTimeout(() => fetchNasabah(searchQuery.value), 300)
}
// Lewat search_link (persis frm.set_query desk): ia meneruskan `filters` ke
// custom query search_close_nasabah, yang mengotorisasi lewat TTS-nya sendiri,
// mengunci ke kontrak aktivitas bila ada, dan membuang kontrak yang sudah
// diklaim aktivitas lain pada sumber yang sama.
async function fetchNasabah(q) {
	const nasabahDoctype = NASABAH_DOCTYPE_BY_SUMBER[form.sumber]
	if (!nasabahDoctype) {
		searchResults.value = []
		return
	}
	searching.value = true
	try {
		const params = new URLSearchParams({
			doctype: nasabahDoctype,
			txt: (q || '').trim(),
			query: 'juragan.collection.doctype.tts.tts.search_close_nasabah',
			filters: JSON.stringify({
				nomor_tts: name.value,
				sumber: form.sumber,
				jalur_close: JALUR_CLOSE,
			}),
			page_length: '20',
		})
		const res = await fetch(
			`/api/method/frappe.desk.search.search_link?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		const recs = (await res.json())?.message || []
		// recs = [{ value: no_perjanjian, description: nama_nasabah }]
		searchResults.value = recs.map((r) => ({
			name: String(r.value),
			nama_nasabah: r.description || '',
		}))
	} catch (e) {
		searchResults.value = []
	} finally {
		searching.value = false
	}
}
function resetPreview() {
	preview.nama_nasabah = ''
	preview.nopol = ''
	preview.no_mesin = ''
	preview.angsuran = null
	preview.angsuran_ke = ''
	preview.tanggal_jto = ''
}
async function selectNasabah(r) {
	form.no_perjanjian = r.name
	searchQuery.value = r.name
	searchOpen.value = false
	closeError.value = ''
	// Satu panggilan server: nama field no mesin berbeda antara KSP ('mesin') dan
	// JG ('no_mesin'), dan Target dan Realisasi harus dicari per nasabah_doctype —
	// keduanya sudah ditangani get_close_dipakai_preview, yang juga dipakai desk.
	previewLoading.value = true
	resetPreview()
	try {
		const data = await call('juragan.collection.doctype.tts.tts.get_close_dipakai_preview', {
			nomor_tts: name.value,
			sumber: form.sumber,
			no_perjanjian: r.name,
			jalur_close: JALUR_CLOSE,
		})
		preview.nama_nasabah = data?.nama_nasabah || r.nama_nasabah || ''
		preview.nopol = data?.nopol || ''
		preview.no_mesin = data?.no_mesin || ''
		preview.angsuran = data?.angsuran ?? null
		preview.tanggal_jto = data?.tanggal_jto || ''
		preview.angsuran_ke = data?.angsuran_ke || ''
	} catch (e) {
		/* preview gagal → biarkan '—'; server tetap fetch ulang saat submit */
	} finally {
		previewLoading.value = false
	}
}

// File untuk Rusak (foto) / Hilang (dokumen STPL).
const fileInput = ref(null)
const pickedFile = ref(null)
const fileName = computed(() => pickedFile.value?.name || '')
const fileAccept = computed(() => (selectedType.value === 'Hilang' ? '.pdf,image/*' : 'image/*'))

function openClose() {
	resetForm()
	closeOpen.value = true
	loadCloseContext()
}
function closeSheet() {
	closeOpen.value = false
}
function resetForm() {
	selectedType.value = ''
	submitting.value = false
	closeError.value = ''
	form.sumber = ''
	form.no_perjanjian = ''
	form.nominal_bayar = null
	// Default hari ini, sama dgn field Tanggal Pembayaran di dialog Close TTS desk.
	form.tanggal_pembayaran = ymd(new Date())
	form.keterangan = ''
	pickedFile.value = null
	searchQuery.value = ''
	searchOpen.value = false
	searchResults.value = []
	resetPreview()
}
function selectType(key) {
	selectedType.value = key
	closeError.value = ''
	pickedFile.value = null
}

// ---- Kalender custom (Tanggal Pembayaran) ----------------------------------
const showDateSheet = ref(false)
const calCursor = ref(new Date()) // bulan tampil (tgl 1)
const WEEKDAYS = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']
const MONTHS = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]
function ymd(d) {
	const m = String(d.getMonth() + 1).padStart(2, '0')
	const day = String(d.getDate()).padStart(2, '0')
	return `${d.getFullYear()}-${m}-${day}`
}
function parseYmd(s) {
	const [y, m, d] = String(s).split('-').map(Number)
	return new Date(y, (m || 1) - 1, d || 1)
}
const calLabel = computed(
	() => `${MONTHS[calCursor.value.getMonth()]} ${calCursor.value.getFullYear()}`
)
const calDays = computed(() => {
	const year = calCursor.value.getFullYear()
	const month = calCursor.value.getMonth()
	const first = new Date(year, month, 1)
	const startOffset = (first.getDay() + 6) % 7 // Senin = 0
	const daysInMonth = new Date(year, month + 1, 0).getDate()
	const cells = []
	for (let i = 0; i < startOffset; i++) cells.push(null)
	for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d))
	return cells
})
function prevMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() - 1, 1)
}
function nextMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() + 1, 1)
}
function dayClass(date) {
	const s = ymd(date)
	if (s === form.tanggal_pembayaran)
		return 'rounded-full bg-primary font-semibold text-ui-onPrimary'
	if (s === ymd(new Date())) return 'rounded-full font-semibold text-primary'
	return 'rounded-full text-ui-ink-gray-700 hover:bg-ui-surface-gray-100'
}
function openDatePicker() {
	const base = form.tanggal_pembayaran || ymd(new Date())
	const d = parseYmd(base)
	calCursor.value = new Date(d.getFullYear(), d.getMonth(), 1)
	showDateSheet.value = true
}
function pickDay(date) {
	form.tanggal_pembayaran = ymd(date)
	showDateSheet.value = false
}

