}
// Foto diperkecil di perangkat saat dipilih (lihat siapkanBerkas); batas 3 MB
// berlaku untuk hasilnya, jadi foto kamera besar tidak lagi ditolak.
async function onFileChange(e) {
	const f = e.target.files?.[0]
	e.target.value = '' // izinkan pilih file sama lagi
	if (!f) return
	pickedFile.value = null
	try {
		pickedFile.value = await siapkanBerkas(f, { maxMb: 3 })
		closeError.value = ''
	} catch (err) {
		closeError.value = err.message
	}
}

async function submitClose() {
	if (!selectedType.value || submitting.value) return
	closeError.value = ''

	// Validasi client per tipe (server tetap validasi ulang).
	if (selectedType.value === 'Dipakai') {
		if (!form.sumber) return (closeError.value = 'Sumber wajib dipilih (KSP atau JG).')
		if (!form.no_perjanjian.trim()) return (closeError.value = 'No Perjanjian wajib diisi.')
		if (!form.nominal_bayar) return (closeError.value = 'Nominal Bayar wajib diisi.')
		if (!form.tanggal_pembayaran) return (closeError.value = 'Tanggal Pembayaran wajib diisi.')
		if (!pickedFile.value) return (closeError.value = 'Foto TTS wajib diunggah.')
	} else if (!pickedFile.value) {
		return (closeError.value =
			selectedType.value === 'Rusak'
				? 'Foto bukti wajib diunggah.'
				: 'Dokumen STPL wajib diunggah.')
	}

	submitting.value = true
	try {
		const args = { nomor_tts: name.value, tipe_close: selectedType.value }
		if (form.keterangan.trim()) args.keterangan = form.keterangan.trim()
		// Semua tipe kini membawa satu berkas: Foto TTS (Dipakai), Foto Rusak, atau STPL.
		const fileUrl = await unggahLampiran(pickedFile.value, DOCTYPE)
		if (!fileUrl) throw new Error('Upload file gagal.')
		if (selectedType.value === 'Dipakai') {
			args.sumber = form.sumber
			args.no_perjanjian = form.no_perjanjian.trim()
			args.nominal_bayar = form.nominal_bayar
			args.tanggal_pembayaran = form.tanggal_pembayaran
			args.foto_tts = fileUrl
		} else if (selectedType.value === 'Rusak') {
			args.foto_rusak = fileUrl
		} else {
			args.dokumen_stpl = fileUrl
		}
		const r = await call('juragan.collection.doctype.tts.tts.close_tts', args)
		closeOpen.value = false
		doc.fetch() // refresh status → tombol Close hilang bila sudah pindah state
		await loadActionState()
		autoToast('success', r?.message || 'Close TTS berhasil.')
	} catch (e) {
		closeError.value =
			e?.messages?.[0] || e?.message || String(e) || 'Gagal melakukan Close TTS.'
	} finally {
		submitting.value = false
	}
}

