// Picker PIC Baru lewat custom query yang sama dengan desk: search_target_pic
// membatasi ke Mapping Collector aktif di cabang dokumen dan membuang PIC lama.
async function fetchPic(q) {
	picSearching.value = true
	try {
		const params = new URLSearchParams({
			doctype: 'Mapping Collector',
			txt: (q || '').trim(),
			query: 'juragan.collection.oper_pic.search_target_pic',
			filters: JSON.stringify({ parent_doctype: DOCTYPE, parent_name: name.value }),
			page_length: '20',
		})
		const res = await fetch(
			`/api/method/frappe.desk.search.search_link?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		const recs = (await res.json())?.message || []
		picResults.value = recs.map((r) => ({
			name: String(r.value),
			nama: r.label || '',
			keterangan: r.description || '',
		}))
	} catch (e) {
		picResults.value = []
	} finally {
		picSearching.value = false
	}
}

function selectPic(r) {
	operForm.pic_baru = r.name
	operForm.nama_pic_baru = r.nama
